def _clean_digits(value):
    if not isinstance(value, str):
        return None
    cleaned = value.replace(" ", "").replace("-", "")
    if not cleaned or any(char < "0" or char > "9" for char in cleaned):
        return None
    return cleaned


def is_valid(number):
    digits = _clean_digits(number)
    if digits is None or len(digits) < 2:
        return False

    total = 0
    for index, digit in enumerate(reversed(digits)):
        value = ord(digit) - ord("0")
        if index % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value
    return total % 10 == 0


def check_digit(partial):
    digits = _clean_digits(partial)
    if digits is None:
        raise ValueError("partial must contain one or more ASCII digits")

    for digit in "0123456789":
        if is_valid(digits + digit):
            return digit
    raise ValueError("unable to calculate check digit")
